// Windows atomic replacement can deny access while an ordinary reader holds the
// destination. Keep the old cache and the serialized temporary file intact while
// briefly retrying this specific transient failure; permanent failures still escape.
var deniedAttempts = 0
while (true) {
  com.intellij.openapi.progress.ProgressManager.checkCanceled()
  try {
    try {
      Files.move(tmpFile, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING)
    }
    catch (e: AtomicMoveNotSupportedException) {
      LOG.warn(e)
      Files.move(tmpFile, file, StandardCopyOption.REPLACE_EXISTING)
    }
    break
  }
  catch (e: java.nio.file.AccessDeniedException) {
    if (!com.intellij.openapi.util.SystemInfoRt.isWindows || ++deniedAttempts >= 20) throw e
    try {
      Thread.sleep(10)
    }
    catch (interrupted: InterruptedException) {
      Thread.currentThread().interrupt()
      throw java.io.InterruptedIOException("Interrupted while replacing project model cache").apply { initCause(interrupted) }
    }
  }
}
